import React, { useState } from 'react';
import {
  Box,
  Button,
  Container,
  Grid,
  MenuItem,
  TextField,
  Typography,
  Select,
  InputLabel,
  FormControl,
  Snackbar,
  Alert,
  Checkbox,
  FormControlLabel,
  IconButton,
  Divider
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import { SelectChangeEvent } from '@mui/material/Select';
import PhotoCamera from '@mui/icons-material/PhotoCamera';
import logo from '../logo.png';

const programs = [
  'Diploma in Colour Therapy',
  'Certificate in Holistic Healing',
  'Advanced Colour Science',
  'Other'
];

const genders = ['Male', 'Female', 'Other'];

// Add a constant for max file size
const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE = MAX_FILE_SIZE_MB * 1024 * 1024;

// Helper for preview
const renderFilePreview = (file: File | null) => {
  if (!file) return null;
  const isImage = file.type.startsWith('image/');
  if (isImage) {
    const url = URL.createObjectURL(file);
    return <img src={url} alt="preview" style={{ maxWidth: 80, maxHeight: 80, borderRadius: 4, marginRight: 8, border: '1px solid #eee' }} onLoad={() => URL.revokeObjectURL(url)} />;
  }
  // For PDF or other files
  return <span style={{ marginRight: 8 }}>{file.name}</span>;
};

const AdmissionForm = () => {
  // Calculate session years dynamically
  const currentYear = new Date().getFullYear();
  const session = `${currentYear}-${currentYear + 1}`;
  const [form, setForm] = useState({
    fullName: '',
    fatherName: '',
    age: '',
    email: '',
    phone: '',
    emergencyContact: '',
    dob: '',
    gender: '',
    nationality: '',
    address: '',
    education: [
      { institution: '', degree: '', year: '', file: null as File | null }
    ],
    program: '',
    sop: '',
    cnic: null as File | null,
    domicile: null as File | null,
    passport: null as File | null,
    passportPhoto: null as File | null,
    digitalSignature: null as File | null,
  });
  const [errors, setErrors] = useState<any>({});
  const [success, setSuccess] = useState(false);
  const [agree, setAgree] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSelect = (e: SelectChangeEvent) => {
    const name = e.target.name as string;
    setForm({ ...form, [name]: e.target.value });
  };

  const handlePassportPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (file.size > MAX_FILE_SIZE) {
        setErrors((prev: any) => ({ ...prev, passportPhoto: `File size must be less than ${MAX_FILE_SIZE_MB}MB` }));
        return;
      }
      setForm({ ...form, passportPhoto: file });
      setErrors((prev: any) => ({ ...prev, passportPhoto: undefined }));
    }
  };

  // Education table handlers
  type EducationField = 'institution' | 'degree' | 'year';
  const handleEducationChange = (idx: number, field: EducationField, value: string) => {
    const newEducation = [...form.education];
    newEducation[idx][field] = value;
    setForm({ ...form, education: newEducation });
  };

  const addEducationRow = () => {
    setForm({ ...form, education: [...form.education, { institution: '', degree: '', year: '', file: null }] });
  };

  const removeEducationRow = (idx: number) => {
    const newEducation = form.education.filter((_, i) => i !== idx);
    setForm({ ...form, education: newEducation });
  };

  const handleEducationFile = (idx: number, file: File | null) => {
    const newEducation = [...form.education];
    newEducation[idx].file = file;
    setForm({ ...form, education: newEducation });
  };

  const validate = () => {
    const newErrors: any = {};
    if (!form.fullName) newErrors.fullName = 'Full name is required';
    if (!form.fatherName) newErrors.fatherName = 'Father name is required';
    if (!form.age || isNaN(Number(form.age)) || Number(form.age) <= 0) newErrors.age = 'Valid age is required';
    if (!form.email) newErrors.email = 'Email is required';
    else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) newErrors.email = 'Invalid email';
    if (!form.phone) newErrors.phone = 'Phone is required';
    if (!form.emergencyContact) newErrors.emergencyContact = 'Emergency contact is required';
    else if (!/^\+\d{10,15}$/.test(form.emergencyContact)) newErrors.emergencyContact = 'Enter a valid international mobile number (e.g. +923001234567)';
    if (!form.dob) newErrors.dob = 'Date of birth is required';
    if (!form.gender) newErrors.gender = 'Gender is required';
    if (!form.nationality) newErrors.nationality = 'Nationality is required';
    if (!form.address) newErrors.address = 'Address is required';
    // Education validation
    if (!form.education || form.education.length === 0) {
      newErrors.education = 'At least one previous education entry is required';
    } else {
      const rowErrors: string[] = [];
      form.education.forEach((row, idx) => {
        if (!row.institution || !row.degree || !row.year || !row.file) {
          rowErrors[idx] = 'All fields and file are required';
        }
      });
      if (rowErrors.length > 0) newErrors.educationRows = rowErrors;
    }
    if (!form.program) newErrors.program = 'Intended program is required';
    if (!form.sop) newErrors.sop = 'Statement of purpose is required';
    if (!form.cnic) newErrors.cnic = 'CNIC card upload is required';
    if (!form.domicile) newErrors.domicile = 'Domicile upload is required';
    if (!form.passportPhoto) newErrors.passportPhoto = 'Passport size photo is required';
    if (!form.digitalSignature) newErrors.digitalSignature = 'Digital signature is required';
    if (!agree) newErrors.agree = 'You must agree that the information provided is correct.';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      setSuccess(true);
      setForm({
        fullName: '',
        fatherName: '',
        age: '',
        email: '',
        phone: '',
        emergencyContact: '',
        dob: '',
        gender: '',
        nationality: '',
        address: '',
        education: [
          { institution: '', degree: '', year: '', file: null }
        ],
        program: '',
        sop: '',
        cnic: null,
        domicile: null,
        passport: null,
        passportPhoto: null,
        digitalSignature: null,
      });
    }
  };

  return (
    <Container maxWidth="lg" sx={{ py: 8 }}>
      <Typography variant="h2" sx={{ fontWeight: 700, textAlign: 'center', mb: 4 }}>
        Student Admission Form for the session {session}
      </Typography>
      <Box component="form" onSubmit={handleSubmit} sx={{ position: 'relative', background: '#fff', borderRadius: 4, boxShadow: 2, p: 4, maxWidth: 1200, mx: 'auto' }}>
      {/* Header inside the form, above Session/Batch field */}
      <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 2 }}>
        <img src={logo} alt="Institute Logo" style={{ width: 80, height: 80, objectFit: 'contain', marginBottom: 12 }} />
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1, textAlign: 'center', letterSpacing: 1 }}>
          Khawaja Shamsuddin Azeemi Institute of Colour Therapy
        </Typography>
        <Typography variant="body1" sx={{ color: 'text.secondary', textAlign: 'center' }}>
        Address: Tariq Gardens, Lahore, Pakistan
        </Typography>
        <Typography variant="body1" sx={{ color: 'text.secondary', textAlign: 'center' }}>
          Email: azeemi.colourtherapy@gmail.com
        </Typography>
      </Box>
      <Divider sx={{ mb: 3 }} />
      {/* Fields area with relative positioning for image box */}
      <Box sx={{ position: 'relative' }}>
        {/* Absolutely positioned passport photo box for desktop, now relative to fields area */}
        <Box
          sx={{
            position: { xs: 'static', md: 'absolute' },
            top: { md: 0, xs: 'auto' },
            marginTop:'16px',
            right: { md: 0, xs: 'auto' },
            width: 140,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            zIndex: 2,
            mb: { xs: 2, md: 0 }
          }}
        >
          <Typography variant="subtitle1" sx={{ mb: 1 }}>Passport Size Photo</Typography>
          <Box
            sx={{
              width: 120,
              height: 150,
              border: errors.passportPhoto ? '2px solid #d32f2f' : '2px dashed #bdbdbd',
              borderRadius: 2,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              background: '#fafafa',
              position: 'relative',
              cursor: 'pointer',
              overflow: 'hidden',
              mb: 1
            }}
            component="label"
          >
            {form.passportPhoto ? (
              <>
                <img
                  src={URL.createObjectURL(form.passportPhoto)}
                  alt="Passport Preview"
                  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                  onLoad={e => URL.revokeObjectURL((e.target as HTMLImageElement).src)}
                />
                <IconButton
                  size="small"
                  sx={{
                    position: 'absolute',
                    top: 4,
                    right: 4,
                    background: 'rgba(255,255,255,0.7)',
                    zIndex: 2
                  }}
                  onClick={e => {
                    e.stopPropagation();
                    setForm({ ...form, passportPhoto: null });
                  }}
                >
                  <DeleteIcon fontSize="small" />
                </IconButton>
              </>
            ) : (
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', color: '#bdbdbd' }}>
                <PhotoCamera sx={{ fontSize: 40, mb: 1 }} />
                <Typography variant="caption" align="center">Click to upload\n(120x150px, JPG/PNG)</Typography>
              </Box>
            )}
            <input
              type="file"
              accept="image/*"
              hidden
              onChange={handlePassportPhoto}
            />
          </Box>
          {errors.passportPhoto && <Typography color="error" variant="caption">{errors.passportPhoto}</Typography>}
        </Box>
        {/* Main grid for all fields except the photo box */}
        <Grid container spacing={3} alignItems="flex-start" sx={{ pr: { md: '180px', xs: 0 } }}>
          <Grid item xs={12} md={4}>
            <TextField
              label="Session / Batch"
              name="session"
              value={session}
              fullWidth
              InputProps={{ readOnly: true }}
              variant="outlined"
              sx={{ mt: 0 }}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Full Name"
              name="fullName"
              value={form.fullName}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.fullName}
              helperText={errors.fullName || 'Full Name as per CNIC'}
              sx={{ mt: 0 }}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Father Name"
              name="fatherName"
              value={form.fatherName}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.fatherName}
              helperText={errors.fatherName || 'Father Name as per CNIC'}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Age"
              name="age"
              type="number"
              value={form.age}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.age}
              helperText={errors.age}
              inputProps={{ min: 1 }}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Email"
              name="email"
              value={form.email}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.email}
              helperText={errors.email}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Phone"
              name="phone"
              value={form.phone}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.phone}
              helperText={errors.phone || 'Enter an international mobile number (e.g. +923001234567)'}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Emergency Contact"
              name="emergencyContact"
              value={form.emergencyContact || ''}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.emergencyContact}
              helperText={errors.emergencyContact || 'Enter an international mobile number (e.g. +923001234567)'}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Date of Birth"
              name="dob"
              type="date"
              value={form.dob}
              onChange={handleChange}
              fullWidth
              required
              InputLabelProps={{ shrink: true }}
              error={!!errors.dob}
              helperText={errors.dob}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <FormControl fullWidth required error={!!errors.gender}>
              <InputLabel>Gender</InputLabel>
              <Select
                name="gender"
                value={form.gender}
                label="Gender"
                onChange={handleSelect}
              >
                {genders.map((g) => (
                  <MenuItem key={g} value={g}>{g}</MenuItem>
                ))}
              </Select>
              {errors.gender && <Typography color="error" variant="caption">{errors.gender}</Typography>}
            </FormControl>
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Nationality"
              name="nationality"
              value={form.nationality}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.nationality}
              helperText={errors.nationality}
            />
          </Grid>
          <Grid item xs={12} md={4}>
            <TextField
              label="Address"
              name="address"
              value={form.address}
              onChange={handleChange}
              fullWidth
              required
              error={!!errors.address}
              helperText={errors.address || 'Full Address as per CNIC'}
            />
          </Grid>
          </Grid>
      </Box>
      {/* Full width: Previous Education and all below */}
      <Box sx={{ mt: 4 }}>
            <Typography variant="h6" sx={{ mb: 1 }}>
              Previous Education
            </Typography>
            <Box sx={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: 8 }}>
                <thead>
                  <tr style={{ background: '#f5f5f5' }}>
                    <th style={{ padding: 8, border: '1px solid #ddd' }}>Institution Name</th>
                    <th style={{ padding: 8, border: '1px solid #ddd' }}>Degree/Certificate</th>
                    <th style={{ padding: 8, border: '1px solid #ddd' }}>Year of Completion</th>
                    <th style={{ padding: 8, border: '1px solid #ddd' }}>Scan File</th>
                    <th style={{ padding: 8, border: '1px solid #ddd' }}></th>
                  </tr>
                </thead>
                <tbody>
                  {form.education.map((row, idx) => (
                    <tr key={idx}>
                      <td style={{ padding: 8, border: '1px solid #ddd' }}>
                        <TextField
                          name={`institution-${idx}`}
                          value={row.institution}
                          onChange={e => handleEducationChange(idx, 'institution', e.target.value)}
                          placeholder="Institution Name"
                          size="small"
                          fullWidth
                        />
                      </td>
                      <td style={{ padding: 8, border: '1px solid #ddd' }}>
                        <TextField
                          name={`degree-${idx}`}
                          value={row.degree}
                          onChange={e => handleEducationChange(idx, 'degree', e.target.value)}
                          placeholder="Degree/Certificate"
                          size="small"
                          fullWidth
                        />
                      </td>
                      <td style={{ padding: 8, border: '1px solid #ddd' }}>
                        <TextField
                          name={`year-${idx}`}
                          value={row.year}
                          onChange={e => handleEducationChange(idx, 'year', e.target.value)}
                          placeholder="Year"
                          size="small"
                          fullWidth
                        />
                      </td>
                      <td style={{ padding: 8, border: '1px solid #ddd' }}>
                        <Button
                          variant="contained"
                          component="label"
                          color={row.file ? 'primary' : 'secondary'}
                          size="small"
                          sx={{ minWidth: 120 }}
                        >
                          {row.file ? row.file.name : 'Upload Scan'}
                          <input
                            type="file"
                            accept="application/pdf,image/*"
                            hidden
                            onChange={e => {
                              if (e.target.files && e.target.files[0]) {
                                const file = e.target.files[0];
                                if (file.size > MAX_FILE_SIZE) {
                                  setErrors((prev: any) => {
                                    const newEd = { ...(prev.educationRows || []) };
                                    newEd[idx] = `File size must be less than ${MAX_FILE_SIZE_MB}MB`;
                                    return { ...prev, educationRows: newEd };
                                  });
                                  return;
                                }
                                handleEducationFile(idx, file);
                                setErrors((prev: any) => {
                                  const newEd = { ...(prev.educationRows || []) };
                                  newEd[idx] = undefined;
                                  return { ...prev, educationRows: newEd };
                                });
                              }
                            }}
                          />
                        </Button>
                      </td>
                      <td style={{ padding: 8, border: '1px solid #ddd', textAlign: 'center' }}>
                        {form.education.length > 1 && (
                          <Button color="error" onClick={() => removeEducationRow(idx)} size="small">Remove</Button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <Button variant="outlined" onClick={addEducationRow} size="small">Add Row</Button>
              {errors.education && <Typography color="error" variant="caption" display="block">{errors.education}</Typography>}
              {Array.isArray(errors.educationRows) && errors.educationRows.some(Boolean) && (
                <Box>
                  {errors.educationRows.map((msg: string, idx: number) =>
                    msg ? (
                      <Typography key={idx} color="error" variant="caption" display="block">Row {idx + 1}: {msg}</Typography>
                    ) : null
                  )}
                </Box>
              )}
            </Box>
            </Box>
      {/* Full width: CNIC, Domicile, Digital Signature uploads */}
      <Box sx={{ mt: 4, mb: 2 }}>
        <Grid container spacing={3}>
          {/* CNIC Upload */}
          <Grid item xs={12} md={4}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>CNIC (Front/Back)</Typography>
            <Box
              sx={{
                width: '100%',
                minHeight: 56,
                border: errors.cnic ? '2px solid #d32f2f' : '2px dashed #bdbdbd',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                background: '#fafafa',
                position: 'relative',
                cursor: 'pointer',
                overflow: 'hidden',
                px: 2,
                py: 1
              }}
              component="label"
            >
              {form.cnic ? (
                <>
                  {renderFilePreview(form.cnic)}
                  <IconButton
                    size="small"
                    sx={{ ml: 1 }}
                    onClick={e => {
                      e.stopPropagation();
                      setForm({ ...form, cnic: null });
                    }}
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </>
              ) : (
                <Typography variant="caption" sx={{ color: '#bdbdbd' }}>Click to upload CNIC (PDF/JPG/PNG)</Typography>
              )}
              <input
                type="file"
                accept="application/pdf,image/*"
                hidden
                onChange={e => {
                  if (e.target.files && e.target.files[0]) {
                    const file = e.target.files[0];
                    if (file.size > MAX_FILE_SIZE) {
                      setErrors((prev: any) => ({ ...prev, cnic: `File size must be less than ${MAX_FILE_SIZE_MB}MB` }));
                      return;
                    }
                    setForm({ ...form, cnic: file });
                    setErrors((prev: any) => ({ ...prev, cnic: undefined }));
                  }
                }}
              />
            </Box>
            {errors.cnic && <Typography color="error" variant="caption">{errors.cnic}</Typography>}
          </Grid>
          {/* Domicile Upload */}
          <Grid item xs={12} md={4}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>Domicile</Typography>
            <Box
              sx={{
                width: '100%',
                minHeight: 56,
                border: errors.domicile ? '2px solid #d32f2f' : '2px dashed #bdbdbd',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                background: '#fafafa',
                position: 'relative',
                cursor: 'pointer',
                overflow: 'hidden',
                px: 2,
                py: 1
              }}
              component="label"
            >
              {form.domicile ? (
                <>
                  {renderFilePreview(form.domicile)}
                  <IconButton
                    size="small"
                    sx={{ ml: 1 }}
                    onClick={e => {
                      e.stopPropagation();
                      setForm({ ...form, domicile: null });
                    }}
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </>
              ) : (
                <Typography variant="caption" sx={{ color: '#bdbdbd' }}>Click to upload Domicile (PDF/JPG/PNG)</Typography>
              )}
              <input
                type="file"
                accept="application/pdf,image/*"
                hidden
                onChange={e => {
                  if (e.target.files && e.target.files[0]) {
                    const file = e.target.files[0];
                    if (file.size > MAX_FILE_SIZE) {
                      setErrors((prev: any) => ({ ...prev, domicile: `File size must be less than ${MAX_FILE_SIZE_MB}MB` }));
                      return;
                    }
                    setForm({ ...form, domicile: file });
                    setErrors((prev: any) => ({ ...prev, domicile: undefined }));
                  }
                }}
              />
            </Box>
            {errors.domicile && <Typography color="error" variant="caption">{errors.domicile}</Typography>}
          </Grid>
          {/* Digital Signature Upload */}
          <Grid item xs={12} md={4}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>Digital Signature (As per CNIC)</Typography>
            <Box
              sx={{
                width: '100%',
                minHeight: 56,
                border: errors.digitalSignature ? '2px solid #d32f2f' : '2px dashed #bdbdbd',
                borderRadius: 2,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                background: '#fafafa',
                position: 'relative',
                cursor: 'pointer',
                overflow: 'hidden',
                px: 2,
                py: 1
              }}
              component="label"
            >
              {form.digitalSignature ? (
                <>
                  {renderFilePreview(form.digitalSignature)}
                  <IconButton
                    size="small"
                    sx={{ ml: 1 }}
                    onClick={e => {
                      e.stopPropagation();
                      setForm({ ...form, digitalSignature: null });
                    }}
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </>
              ) : (
                <Typography variant="caption" sx={{ color: '#bdbdbd' }}>Click to upload Digital Signature (PDF/JPG/PNG)</Typography>
              )}
              <input
                type="file"
                accept="application/pdf,image/*"
                hidden
                onChange={e => {
                  if (e.target.files && e.target.files[0]) {
                    const file = e.target.files[0];
                    if (file.size > MAX_FILE_SIZE) {
                      setErrors((prev: any) => ({ ...prev, digitalSignature: `File size must be less than ${MAX_FILE_SIZE_MB}MB` }));
                      return;
                    }
                    setForm({ ...form, digitalSignature: file });
                    setErrors((prev: any) => ({ ...prev, digitalSignature: undefined }));
                  }
                }}
              />
            </Box>
            {errors.digitalSignature && <Typography color="error" variant="caption">{errors.digitalSignature}</Typography>}
          </Grid>
        </Grid>
      </Box>
      {/* Full width: Undertaking, submit button, etc. */}
      <Box sx={{ mt: 4 }}>
            <Box sx={{ mb: 2, p: 2, background: '#f8f9fb', borderRadius: 2, border: '1px solid #e0e0e0' }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                Undertaking
              </Typography>
              <Typography variant="body2" sx={{ whiteSpace: 'pre-line', mb: 1 }}>
                {`I fully understand and agree to the following terms:

I will abide by all the rules, regulations, policies, and code of conduct set forth by the institute.

I will maintain discipline, punctuality, and respect toward teachers, staff, and fellow students.

I will not engage in any activity that may disrupt the academic environment or bring disrepute to the institution.

I understand that submission of false information or documents may result in immediate cancellation of my admission.

I undertake to attend classes regularly and fulfill the academic and attendance requirements as prescribed by the institute.

I accept that the institution has the right to take disciplinary action against me, including suspension or expulsion, in case of violation of rules.

I will not hold the institution liable for any personal loss, injury, or damage incurred on or off campus during my tenure as a student.

I have read and understood all the terms mentioned above and undertake to comply with them throughout the duration of my studies.`}
              </Typography>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={agree}
                    onChange={e => {
                      if (!agree && !validate()) {
                        setAgree(false);
                        return;
                      }
                      setAgree(e.target.checked);
                    }}
                    color="primary"
                  />
                }
                label={<Typography variant="body2">I accept and agree to the above undertaking.</Typography>}
              />
              {errors.agree && (
                <Typography color="error" variant="caption" display="block">{errors.agree}</Typography>
              )}
            </Box>
            <Button
              type="submit"
              variant="contained"
              color="primary"
              size="large"
              fullWidth
              sx={{ py: 2, mt: 2 }}
              disabled={!agree}
            >
              Submit Application
            </Button>
      </Box>
      {/* End of form fields and grid */}
      </Box>
      <Snackbar open={success} autoHideDuration={6000} onClose={() => setSuccess(false)}>
        <Alert onClose={() => setSuccess(false)} severity="success" sx={{ width: '100%' }}>
          Application submitted successfully!
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default AdmissionForm; 