import React from 'react';
import styles from './Navbar.module.css';
import logo from '../../logo.png';
import { Link } from 'react-router-dom';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import useMediaQuery from '@mui/material/useMediaQuery';
import { useTheme } from '@mui/material/styles';

export const ADMISSIONS_OPEN = true; // Toggle this to control visibility

// Shared nav links for both desktop and mobile
export const navLinks = [
  { label: 'ACCREDITATION', to: '/#accreditation' },
  { label: 'INTRODUCTION', to: '/#introduction' },
  { label: 'CURRICULUM', to: '/#curriculum' },
  { label: 'PROGRAM FEATURES', to: '/#program-features' },
  { label: 'CAREER OPPORTUNITIES', to: '/#career-opportunities' },
];

const Navbar = ({ setMobileOpen }: { setMobileOpen: (open: boolean) => void }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  return (
    <nav className={styles.navbar}>
      <div className={styles.leftSection}>
        <a href="https://umer663.github.io/ksaict-website-gh" className={styles.leftSection} style={{ textDecoration: 'none' }}>
          <img src={logo} alt="Logo" className={styles.logo} />
          <div className={styles.brandText}>
            <div className={styles.brandTitle}>KHAWAJA SHAMSUDDIN AZEEMI</div>
            <div className={styles.brandSubtitle}>INSTITUTE OF COLOUR THERAPY</div>
          </div>
        </a>
      </div>
      {isMobile ? (
        <IconButton
          aria-label="open menu"
          onClick={() => setMobileOpen(true)}
          sx={{ marginLeft: 'auto', color: '#7b61ff' }}
        >
          <MenuIcon fontSize="large" />
        </IconButton>
      ) : (
        <>
          <div className={styles.centerSection}>
            {navLinks.map(link => (
              <Link key={link.to} to={link.to} className={styles.link}>{link.label}</Link>
            ))}
            {ADMISSIONS_OPEN && (
              <Link to="/admission" className={styles.link} style={{ textDecoration: 'none' }}>
                ADMISSION
              </Link>
            )}
          </div>
          <div className={styles.rightSection}>
            <Link to="/#contact" className={styles.contactButton} style={{ textDecoration: 'none' }}>CONTACT</Link>
          </div>
        </>
      )}
    </nav>
  );
};

export default Navbar; 